tasks.check:
set -e
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
for f in $(git status --porcelain | grep -v '\.venv' | sed 's/^...//'); do
  case "$f" in
    data/stories/continuity-initiative/pacing.yaml|tests/test_recovery_after_choice.py) ;;
    *) echo "WHY: edited file outside ownership: $f"; exit 1;;
  esac
done
git diff --quiet HEAD -- storygame packages tests/test_stall_exit_audit.py tests/test_2c_ledger_guard.py tests/test_canon_journey.py || { echo "WHY: engine or protected tests edited"; exit 1; }
[ -f tests/test_recovery_after_choice.py ] || { echo "WHY: tests/test_recovery_after_choice.py missing"; exit 1; }
N2A=$($PY -m pytest --collect-only -q -p no:cacheprovider tests/test_recovery_after_choice.py 2>/dev/null | grep -c '_2a_')
N2C=$($PY -m pytest --collect-only -q -p no:cacheprovider tests/test_recovery_after_choice.py 2>/dev/null | grep -c '_2c_')
[ "$N2A" -ge 6 ] || { echo "WHY: only $N2A 2A test cases (need >= 6: two outcomes at three timings)"; exit 1; }
[ "$N2C" -ge 4 ] || { echo "WHY: only $N2C 2C test cases"; exit 1; }
$PY - <<'EOF'
import subprocess, yaml
old = yaml.safe_load(subprocess.run(["git","show","HEAD:data/stories/continuity-initiative/pacing.yaml"],capture_output=True,text=True,check=True).stdout)
new = yaml.safe_load(open("data/stories/continuity-initiative/pacing.yaml"))
def evs(d):
    out = {}
    def walk(x):
        if isinstance(x, dict):
            if "id" in x and "scene_id" in x and ("at_turn" in x or "when" in x): out[x["id"]] = x
            for v in x.values(): walk(v)
        elif isinstance(x, list):
            for v in x: walk(v)
    walk(d); return out
a, b = evs(old), evs(new)
assert set(a) == set(b), "WHY: event ids changed"
changed = sorted(i for i in a if a[i] != b[i])
assert "inspection_recovery_2a" in changed, "WHY: inspection_recovery_2a was not guarded (2A flaw is proven by the plan's own symptom)"
assert set(changed) <= {"inspection_recovery_2a", "purge_recovery_2c"}, f"WHY: unexpected events changed: {changed}"
ALLOWED = {"restricted_corridor_access", "supervisor_convinced", "committed_to_transmit", "committed_to_rescue"}
for i in changed:
    added = [w for w in b[i]["when"] if w not in a[i]["when"]]
    assert added and all(w.get("fact_id") in ALLOWED and w.get("equals") is False and set(w) == {"fact_id","equals"} for w in added), f"WHY: {i}: bad added conditions {added}"
    assert all(w in b[i]["when"] for w in a[i]["when"]), f"WHY: {i}: existing conditions removed"
    assert {k: v for k, v in b[i].items() if k != "when"} == {k: v for k, v in a[i].items() if k != "when"}, f"WHY: {i}: other fields changed"
print("data ok, changed:", changed)
EOF
# mutation check: the 2A tests must FAIL on the unfixed pacing
cp data/stories/continuity-initiative/pacing.yaml /tmp/pacing.fixed.$$
git show HEAD:data/stories/continuity-initiative/pacing.yaml > data/stories/continuity-initiative/pacing.yaml
if $PY -m pytest -q -n0 -p no:cacheprovider tests/test_recovery_after_choice.py -k "_2a_" > /tmp/mut.log 2>&1; then cp /tmp/pacing.fixed.$$ data/stories/continuity-initiative/pacing.yaml; echo "WHY: the 2A tests PASS without the fix, so they do not prove the flaw"; exit 1; fi
cp /tmp/pacing.fixed.$$ data/stories/continuity-initiative/pacing.yaml
echo "mutation ok (2A tests fail without the fix)"
$PY -m pytest -q -n0 -p no:cacheprovider tests/test_recovery_after_choice.py tests/test_2c_ledger_guard.py tests/test_stall_exit_audit.py tests/test_canon_journey.py tests/test_spine_expected_reveals.py tests/test_incident_engine.py tests/test_incident_loader.py tests/test_incident_pressure.py tests/test_incident_recovery.py tests/test_pacing_handoff.py tests/test_scene_relative_pacing.py tests/test_evidence_gap_journeys.py tests/test_evidence_penalty.py tests/test_markdown_story_package.py $(ls tests/test_2a_*.py tests/test_2b_*.py tests/test_2c_*.py tests/test_3a_*.py 2>/dev/null) > /tmp/r6a.log 2>&1 || { tail -40 /tmp/r6a.log; echo "WHY: focused suites failed"; exit 1; }
tail -3 /tmp/r6a.log
$PY -m ruff format --check . && $PY -m ruff check . || { echo "WHY: ruff"; exit 1; }
OUT=/home/bcorfman/dev/ringer-work/act2-2c-yes
mkdir -p $OUT && git add -A >/dev/null 2>&1 && git diff --cached > $OUT/r6a.patch && wc -l $OUT/r6a.patch && git diff --cached --stat | tail -5
